// Simple per-device cost model snippet (illustrative)
function costPerDevice(modelSizeMB, energyW, updatesPerMonth){
  const energyCost = energyW * 0.01;
  const updateCost = updatesPerMonth * 0.5;
  return modelSizeMB * 0.01 + energyCost + updateCost;
}
```

